 function moveTask(id,q,before=null){view.sort='manual';repo.batch(()=>{const entry=H.findTaskEntry(repo.state.tasks,id);if(!entry)throw Error('任务已不存在');if(entry.parent){if(q!==entry.task.quadrant)repo.updateTask(id,{quadrant:q});else repo.moveSubtask(entry.parent.id,id,before);}else repo.moveTask(id,q,before);repo.updateDemo(d=>{d.ui={...(d.ui||{}),taskSort:'manual'};});});}
 function stepOrder(id,delta){const entry=H.findTaskEntry(repo.state.tasks,id),visible=new Set(visibleBoardTasks().map(t=>t.id)),siblings=entry.siblings.filter(t=>entry.parent||(t.quadrant===entry.task.quadrant&&(route!=='tasks'||visible.has(t.id)))).sort((a,b)=>a.order-b.order||a.createdAt.localeCompare(b.createdAt)||a.id.localeCompare(b.id)),index=siblings.findIndex(t=>t.id===id),target=index+delta;if(target<0||target>=siblings.length)return toast('已在列表边界');const before=delta<0?siblings[target].id:siblings[target+1]?.id||null;moveTask(id,entry.task.quadrant,before);closeModal();toast('已保存任务顺序');}
