 function catalogList(input){const host=input.closest('[data-catalog]');if(!host)return;const kind=host.dataset.catalog,s=repo.state,q=input.value.trim(),items=kind==='projects'?s.projects.filter(p=>!p.archived):s[kind].map(name=>({id:name,name}));let found=items.filter(x=>H.matchesQuery(q,x.name)).slice(0,12);const list=host.querySelector('.catalog-list');list.innerHTML=found.map(x=>'<button type="button" role="option" data-action="catalog-pick" data-id="'+esc(x.id)+'">'+esc(x.name)+(kind==='projects'?' <small>· '+esc(x.id.slice(-10))+'</small>':'')+'</button>').join('')+(q&&!items.some(x=>x.name.normalize('NFKC').toLowerCase()===q.normalize('NFKC').toLowerCase())?'<button type="button" role="option" data-action="catalog-create" data-id="'+esc(q)+'">创建 “'+esc(q)+'”</button>':'');input.setAttribute('aria-expanded',String(!!list.children.length));}
 function pickCatalog(el,create=false){const host=el.closest('[data-catalog]'),kind=host.dataset.catalog,input=host.querySelector('[role=combobox]'),name=el.dataset.id;if(name.length>100&&create)throw Error('分类名称最多100字');let value=name,id=name;if(kind==='projects'){let p=repo.state.projects.find(p=>p.id===name);if(create){const matches=repo.state.projects.filter(p=>!p.archived&&p.name.normalize('NFKC').toLowerCase()===name.normalize('NFKC').toLowerCase());if(matches.length>1)throw Error('项目重名，请选择明确的项目 ID');p=matches[0];if(!p){p={id:'d4-project-'+crypto.randomUUID(),name,description:'',archived:false};transaction(s=>s.projects.push(p));}}if(!p||p.archived)throw Error('项目已删除或已归档');value=p.name;id=p.id;host.querySelector('[name=projectId]').value=id;}
  if(kind==='tags'){const hidden=host.querySelector('[name=tags]'),tags=[...new Set([...JSON.parse(hidden.value),value])];if(tags.length>30)throw Error('最多 30 个标签');hidden.value=JSON.stringify(tags);host.querySelector('.tag-chips').innerHTML=tags.map(t=>'<button type="button" class="tag-chip" data-action="tag-remove" data-id="'+esc(t)+'">'+esc(t)+' ×</button>').join('');input.value='';}else input.value=value;input.focus();host.querySelector('.catalog-list').innerHTML='';input.setAttribute('aria-expanded','false');}
